else if( (tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.closureACT02)) && (tw.local.odcRequest.stepLog.role == String(tw.epv.userRole.hubComp)) )
	tw.local.mailTo = String(tw.epv.Mails.hubComp_Mngr);

//Closure Process - ClosureAct03
else if( tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.closureACT03) )
	tw.local.mailTo = String(tw.epv.Mails.tradeFoMkr_Mngr);	
	
//Closure Process - ClosureAct04
else if( tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.closureACT04) )
	tw.local.mailTo = String(tw.epv.Mails.tradeFoChkr_Mngr);	

//Closure Process - ClosureAct05
else if( tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.closureACT05) )
	tw.local.mailTo = String(tw.epv.Mails.hubMkr_Mngr);	
	
//Closure Process - ClosureAct05
else if( tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.closureACT06) )
	tw.local.mailTo = String(tw.epv.Mails.hubChkr_Mngr);	
	
//Reversal Process - RACT01
else if( tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.RACT01) )
	tw.local.mailTo = String(tw.epv.Mails.hubMkr_Mngr);	
		
//Reversal Process - RACT02
else if( tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.RACT02) )
	tw.local.mailTo = String(tw.epv.Mails.hubChkr_Mngr);	
				
//Collection Process - COL01
else if( tw.local.odcRequest.stepLog.step == String(tw.epv.Col_ScreenNames.ODCCol01) )
	tw.local.mailTo = String(tw.epv.Mails.hubMkr_Mngr);	
		
//Collection Process - COL02
else if( tw.local.odcRequest.stepLog.step == String(tw.epv.Col_ScreenNames.ODCCol02) )
