ns16:scriptTask.ns16:script:
tw.local.activityName= tw.system.findTaskByID(tw.local.taskId).processActivityName;
tw.local.receivedDate = String(tw.system.findTaskByID(tw.local.taskId).activationTime.formatDate("short"));
tw.local.dueDate= String(tw.system.findTaskByID(tw.local.taskId).dueDate.formatDate("short"));
tw.local.owner = tw.system.findTaskByID(tw.local.taskId).owner;

//made by maghroob
tw.local.instanceNum = String(tw.local.odcRequest.instanceNo);
tw.local.currency = String(tw.local.odcRequest.FinancialDetailsBR.currency.name);
tw.local.amount = tw.local.odcRequest.requestType.value == tw.epv.RequestType.Collection+"" ? String(tw.local.odcRequest.OdcCollection.amount) : String(tw.local.odcRequest.FinancialDetailsBR.documentAmount);

//Set Mail Subject
tw.local.subject = "ODC Request No. "+tw.local.odcRequest.requestNo
			+" for Customer "+tw.local.odcRequest.CustomerInfo.customerName
			+" is Past Due "
			+"طلب التحصيل المستندى تصدير رقم "+tw.local.odcRequest.requestNo
			+" للعميل "+tw.local.odcRequest.CustomerInfo.customerName
			+" قد تخطى الوقت المعين للمهمة";

//Create Process - Act01
if( (tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.CACT01)) && (tw.local.odcRequest.stepLog.role == String(tw.epv.userRole.branch)) )
	tw.local.mailTo = String(tw.epv.Mails.branchMkr_Mngr);
else if( (tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.CACT01)) && (tw.local.odcRequest.stepLog.role == String(tw.epv.userRole.hub)) )
	tw.local.mailTo = String(tw.epv.Mails.hubMkr_Mngr);

//Create Process [- Act02		
else if( (tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.CACT02)) && (tw.local.odcRequest.stepLog.role == String(tw.epv.userRole.branchComp)) )
	tw.local.mailTo = tw.epv.Mails.branchComp_Mngr;	

//Create Process - Act03	
else if (tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.CACT03))
	tw.local.mailTo = String(tw.epv.Mails.tradeFO_Mngr);
	
//Create Process - Act04	
else if (tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.CACT04))
	tw.local.mailTo = String(tw.epv.Mails.exeHubMkr_Mngr);	

//Create Process - Act05	
else if (tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.CACT05))
	tw.local.mailTo = String(tw.epv.Mails.exeHubChkr_Mngr);

//Create Process - Act06
else if (tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.CACT06))
	tw.local.mailTo = String(tw.epv.Mails.exeHubChkr_Mngr);		

//Closure Process - ClosureAct01
else if( (tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.closureACT01)) && (tw.local.odcRequest.stepLog.role == String(tw.epv.userRole.branch)) )
	tw.local.mailTo = String(tw.epv.Mails.branchMkr_Mngr);		

else if( (tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.closureACT01)) && (tw.local.odcRequest.stepLog.role == String(tw.epv.userRole.hub)) )
	tw.local.mailTo = String(tw.epv.Mails.hubMkr_Mngr);

//Closure Process - ClosureAct02
else if( (tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.closureACT02)) && (tw.local.odcRequest.stepLog.role == String(tw.epv.userRole.branchComp)) )
	tw.local.mailTo = String(tw.epv.Mails.branchComp_Mngr);		

else if( (tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.closureACT02)) && (tw.local.odcRequest.stepLog.role == String(tw.epv.userRole.hubComp)) )
	tw.local.mailTo = String(tw.epv.Mails.hubComp_Mngr);

